mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT bseq AS seq, activity_type AS boradTitle, activity_code AS boradCode, title AS subject, TO_CHAR(regdate, 'YYYY-MM-DD') AS regdate FROM vwUserAllActivities WHERE user_id = #{seq}
AND ${column} LIKE '%' || #{word} || '%'
ORDER BY regdate DESC ) a ) WHERE rnum BETWEEN #{begin} AND #{end}

SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT parent_post_id AS seq, comment_type AS boradTitle, activity_code AS boradCode, parent_post_title AS subject, content AS commentcontent, TO_CHAR(regdate, 'YYYY-MM-DD') AS regdate FROM vwUserAllComments WHERE user_id = #{seq}
AND ${column} LIKE '%' || #{word} || '%'
ORDER BY regdate DESC ) a ) WHERE rnum BETWEEN #{begin} AND #{end}

SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT post_id AS seq, board_name AS boradTitle, board_type AS boradCode, post_title AS subject, TO_CHAR(regdate, 'YYYY-MM-DD') AS regdate FROM vwUserAllLikes WHERE user_id = #{seq}
AND ${column} LIKE '%' || #{word} || '%'
ORDER BY regdate DESC ) a ) WHERE rnum BETWEEN #{begin} AND #{end}

SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT content_id AS seq, board_name AS boradTitle, content_type AS boradCode, post_title AS subject, TO_CHAR(post_regdate, 'YYYY-MM-DD') AS regdate FROM vwAllScraps WHERE user_id = #{seq}
AND ${column} LIKE '%' || #{word} || '%'
ORDER BY post_regdate DESC ) a ) WHERE rnum BETWEEN #{begin} AND #{end}

SELECT * FROM ( SELECT a.*, ROWNUM AS rnum FROM ( SELECT reservation_id AS seq, user_id AS useq, room_total_price AS roomtotalprice, accom_reservation_id AS accomseq, room_name AS roomname, place_name AS placename, place_address AS placeaddress, room_type AS roomtype, accom_type AS accomtype, guest_count AS guestcount, TO_CHAR(checkin_date, 'YYYY-MM-DD') AS checkindate, TO_CHAR(checkout_date, 'YYYY-MM-DD') AS checkoutdate FROM vwAccomReservAtionDetails WHERE user_id = #{seq} AND status_id != 3
AND ${column} LIKE '%' || #{word} || '%'
ORDER BY reservation_id DESC ) a ) WHERE rnum BETWEEN #{begin} AND #{end}

